-- TEMPLATE. Create BOTH sign-in accounts and link them as "the two of you".
--
-- Do NOT edit this file and commit it. Copy it to  supabase/create-accounts.sql  (that name is gitignored
-- and blocked by the publish guard), fill in the copy, paste it into Supabase > SQL Editor, run it ONCE,
-- then delete the filled-in copy and the saved query in the editor. Passwords must never be committed,
-- pasted into chat, or left in a saved query.
--
-- Run schema.sql first. Use real emails (they are how you reset a forgotten password) and a different
-- strong password for each of you: 12+ characters, no names, nothing used anywhere else.
--
-- This inserts straight into Supabase's auth tables, which works but isn't an officially supported path.
-- The official alternative: Authentication > Users > Add user > Create new user (tick "Auto Confirm User"),
-- then the couple_members insert at the bottom of schema.sql.

create extension if not exists pgcrypto with schema extensions;

do $$
declare
  v   record;
  uid uuid;
begin
  for v in
    select * from (values
      ('YOUR-EMAIL',    'YOUR-PASSWORD',    'a', 'YOUR-NAME'),
      ('PARTNER-EMAIL', 'PARTNER-PASSWORD', 'b', 'PARTNER-NAME')
    ) as t(email, pw, slot, name)
  loop
    if v.email like 'YOUR-%' or v.email like 'PARTNER-%' or v.pw like 'YOUR-%' or v.pw like 'PARTNER-%'
       or v.name like 'YOUR-%' or v.name like 'PARTNER-%' then
      raise exception 'Replace ALL the placeholders (email, password AND name for both of you) first.';
    end if;
    if length(v.pw) < 12 then
      raise exception 'Password for % is too short (use 12+ characters).', v.email;
    end if;
    if exists (select 1 from auth.users where email = lower(v.email)) then
      raise exception '% already has an account. Use Authentication > Users to change it instead.', v.email;
    end if;

    uid := gen_random_uuid();

    insert into auth.users (
      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change, email_change_token_new, email_change_token_current,
      phone_change, phone_change_token, reauthentication_token
    ) values (
      '00000000-0000-0000-0000-000000000000', uid, 'authenticated', 'authenticated', lower(v.email),
      extensions.crypt(v.pw, extensions.gen_salt('bf')), now(),
      '{"provider":"email","providers":["email"]}', '{}', now(), now(),
      '', '', '', '', '', '', '', ''
    );

    insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (gen_random_uuid(), uid, uid::text,
            jsonb_build_object('sub', uid::text, 'email', lower(v.email), 'email_verified', true),
            'email', now(), now(), now());

    insert into public.couple_members (user_id, slot, name) values (uid, v.slot, v.name);
  end loop;
end $$;

-- Check it worked: two rows, slots a and b, with your names.
select u.email, m.slot, m.name
from auth.users u join public.couple_members m on m.user_id = u.id
order by m.slot;
